// Researched meta data (generated by scripts/research/build-meta.ts; see docs/META-RESEARCH.md).
// The bundled meta.json is the fallback; the downloaded dataset can carry a newer one.
import bundled from './meta.json'

export interface TierPicks { S: string[]; A: string[] }
export interface MetaSite {
  /** Replay-format site name, e.g. "B Church, B Arsenal Room". */
  name: string
  kind: 'basement' | 'ground' | 'upper'
  /** Number of lineups behind the tiers per side (0–1 = too thin; curated fallback is used). */
  evidence: { attack: number; defense: number }
  attack: TierPicks
  defense: TierPicks
}
export interface MetaMap {
  sites: MetaSite[]
  /** Strong on this map: pro must-bans (≥25% of games) + operators common across the map's lineups. */
  strong: { attack: string[]; defense: string[] }
  proBans: { games: number; rates: Record<string, number> }
}
export interface MetaData {
  version: string
  season: string
  patch: string
  generatedAt: string
  rankedPool: string[]
  notes: string[]
  ranked: { scope: string; bans: Record<'attack' | 'defense', Record<string, number>>; winDelta: Record<'attack' | 'defense', Record<string, number>> }
  maps: Record<string, MetaMap>
  sources: { name: string; detail: string; url: string }[]
}

let current = bundled as MetaData
export const meta = (): MetaData => current
/** Use a newer researched meta (from the downloaded dataset). */
export function setMeta(m: MetaData | undefined): void { if (m && m.version > current.version) current = m }
